-- Orc origins. DRAFT for the user's approval. Year 1: Thrall freed the camps, built Orgrimmar.
-- Every list ends with "other".
local P = RPGDialogueAPI:Pack("rpgd.world")

P:Origin {
  id = "orc", race = "Orc",
  origins = {
    { id = "orc_camp_born", name = "Born in a human internment camp",
      blurb = "I was born behind a fence, to parents who'd stopped believing they would ever leave it. Thrall opened the gate, and I've been learning what it means to be an orc ever since.",
      nudge = { trait = { stern = 1 }, align = { order = -1 } }, home = "valley_of_trials" },
    { id = "orc_frostwolf", name = "Frostwolf from the Alterac valleys",
      blurb = "My clan never drank the blood and never forgot the old ways. When the Warchief called, some of us came south with wolves at our sides.",
      nudge = { trait = { pious = 1 }, align = { honor = 2 } }, home = "orgrimmar" },
    { id = "orc_warsong_kin", name = "Kin of the Warsong clan",
      blurb = "Hellscream's clan is my clan, and we don't wait for permission. The night elves' forest is full of lumber and full of arrows, and I've dodged both.",
      nudge = { trait = { brave = 1 }, align = { order = -1 } }, home = "splintertree" },
    { id = "orc_razor_hill_grunt", name = "Grunt of the Razor Hill watch", class = "WARRIOR",
      blurb = "Gar'Thok put an axe in my hands and pointed me at the coast. Kul Tiras landed soldiers on it, and I learned what the Horde is for.",
      nudge = { trait = { stern = 1 }, align = { order = 2, honor = 1 } }, home = "razor_hill" },
    { id = "orc_thrall_shaman", name = "Student of the Warchief's shamans", class = "SHAMAN",
      blurb = "Our people forgot the spirits for a generation and paid for it in blood. I'm one of the young ones learning to listen again, and the elements are still deciding whether to forgive us.",
      nudge = { trait = { pious = 1 }, align = { light = 1, order = -1 } }, home = "orgrimmar" },
    { id = "orc_cleft_initiate", name = "Initiate of the Cleft of Shadow", class = "WARLOCK",
      blurb = "The Warchief would rather the old magic stayed buried. The Cleft of Shadow keeps it alive anyway, and I went down there because power is power.",
      nudge = { trait = { curious = 1 }, align = { light = -2 } }, home = "orgrimmar" },
    { id = "orc_camp_primer", name = "Self-taught from a guard's primer", class = "MAGE",
      blurb = "A guard in the camps left a book of letters behind. I taught myself to read from it, then found worse books, and taught myself to burn things.",
      nudge = { trait = { curious = 1 }, align = { order = -1 } } },
    { id = "orc_doomhammer_veteran", name = "Veteran of Doomhammer's Horde", class = "WARRIOR",
      blurb = "I swung an axe at Lordaeron's walls under Doomhammer, then spent fifteen years in a camp too sick with lethargy to lift it. The Warchief gave me back my axe and my reasons, and I'm not wasting either.",
      nudge = { trait = { brave = 1 }, align = { order = 1, honor = 1 } }, home = "orgrimmar" },
    { id = "orc_durotar_tracker", name = "Tracker of the Durotar scrub", class = "HUNTER",
      blurb = "Durotar's soil won't feed a clan, so I learned to feed one with a bow. I've tracked raptors and scorpids from the Valley of Trials to the edge of the Barrens, and I have scars from the ones that tracked me back.",
      nudge = { trait = { cautious = 1 }, align = { order = 1 } }, home = "razor_hill" },
    { id = "orc_barrens_beastmaster", name = "Beastmaster of the Barrens", class = "HUNTER",
      blurb = "I went out to the Crossroads when the Horde first raised its walls, and the Barrens taught me to hunt the way the old clans did, beside a beast I'd tamed myself. A kodo stampede is the closest thing to prayer I know.",
      nudge = { trait = { brave = 1 }, align = { honor = 1, order = -1 } }, home = "crossroads" },
    { id = "orc_drag_runner", name = "Knife-runner of the Drag", class = "ROGUE",
      blurb = "The Drag is where Orgrimmar keeps the business the Warchief doesn't look at too closely, and I grew up running knives and messages through it. I know which merchants pay their debts, and which ones pay someone like me to collect.",
      nudge = { trait = { greedy = 1, witty = 1 }, align = { order = -1, honor = -1 } }, home = "orgrimmar" },
    { id = "orc_blade_hunter", name = "Hunter of Burning Blade cultists", class = "ROGUE",
      blurb = "The Burning Blade still hides in Durotar's caves, worshipping the demons that nearly ended our people. I learned to move quietly so I could find their cultists before they found the next young fool to recruit.",
      nudge = { trait = { stern = 1 }, align = { light = 1, order = 1 } }, home = "razor_hill" },
    { id = "orc_lapsed_warlock_shaman", name = "Warlock's apprentice who turned to the spirits", class = "SHAMAN",
      blurb = "An old warlock taught me his craft in the camps, until the Warchief's shamans showed me another way. The spirits took me back after a long silence, but my fingers still itch for fel fire when I'm angry.",
      nudge = { trait = { stern = 1 }, align = { light = 1, order = 1 } } },
    { id = "orc_blade_defector", name = "Defector from the Burning Blade", class = "WARLOCK",
      blurb = "I wore the Burning Blade's mark in the caves of Durotar until I saw what the demons wanted in return. I walked out with my life and my spells, and the Warchief's grunts still watch me as if I might walk back.",
      nudge = { trait = { cautious = 1 }, align = { light = -1, honor = 1 } }, home = "orgrimmar" },
    { id = "orc_valley_of_spirits_student", name = "Student of the troll mages", class = "MAGE",
      blurb = "Orcs have no arcane tradition, only stories of what the warlocks did with fel. The troll mages in the Valley of Spirits agreed to teach me, and my own clan still checks my eyes for a green glow.",
      nudge = { trait = { curious = 1 }, align = { order = -1, honor = 1 } }, home = "orgrimmar" },
    { id = "orc_blackrock_defector", name = "Blackrock who left Rend's banner",
      blurb = "My clan still follows Rend Blackhand in his mountain and calls him Warchief. I left them for Thrall's Horde, and some nights I wake wondering which of my brothers I'll meet across a battlefield.",
      nudge = { trait = { skeptical = 1 }, align = { honor = 2, order = 1 } } },
    { id = "other", name = "Other" },
  },
}
